// === Tab: mySketch ===
//for the #wccChallenge on the theme of "floating".
//Vacillated quite a bit on the realistic/stylistic spectrum while making this particle system.
//Based it on those galaxies of dust you can sometimes see floating in bright shafts of light inside.
//Always found them visually fascinating.
//The shaft of light here is prerendered for performance. The particles then check that prerendered background
//with the get() method to see how bright they should be lit (lines 114-118).

let bg
let motes=[]
let maxSize=10
let minSize=1
let mouseMoving= false


function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1)
	bg=createGraphics(width, height)
	bg.pixelDensity(1)
	bg.background(0)
	for(let i=0; i<100; i++){
		 bg.noStroke()
		bg.fill(255, 2)
		let v1=createVector(width+width*0.5, random(-height*0.4, 0))
		let v2=createVector(0, height+ random(-height*0.3, height*0.3))
		let beamWidth= random(height*0.05, height)
		bg.triangle(v1.x, v1.y, v2.x, v2.y-beamWidth/2, v2.x, v2.y+beamWidth/2)

	}
	bg.filter(BLUR, 8)
	let m=(width+height)/10
	for(let i=0; i<m; i++){
		motes.push(new mote(random(width), random(height)))
	}
}

function draw() {	
	//print(frameRate())
image(bg, 0, 0)

	for(let mote of motes){
		mote.float();
		mote.replace();
		mote.waveaway();
		mote.show();

	}

	mouseMoving= false
}

function mouseMoved() {
	mouseMoving=true
}


class mote{
	constructor(x, y){
		this.pos=createVector(x, y);
		this.vel=createVector(random(-0.01, -0.3), random(0.01, 0.3));
		this.depth= random(-20, 20)
		this.wave=createVector(0, 0)
	}

	float(){
		this.pos.add(this.vel)
		let waver= map(noise(this.pos.x/100, this.pos.y/100, frameCount/200), 0, 1, -0.2, 0.2)
		this.depth+=waver
		this.depth= constrain(this.depth, -20, 20)

	}

	replace(){
	if(this.pos.x<-maxSize/2 || this.pos.y>height+maxSize/2){	
	let newPlace= random(-width*0.2, height*0.2)
	if(newPlace<0){
	this.pos= createVector(width+newPlace, -maxSize/2)		
	} else{
	this.pos= createVector(width+maxSize/2, newPlace)	
	}	
	}
	}

	waveaway(){
	if(mouseMoving){
		let mpos=createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))
		let d= p5.Vector.dist(this.pos, mpos)
		if(d<200){
		let power= map(d, 0, 200, 3, 0)
		let xnvel= map(noise(this.pos.x/100, frameCount/100, this.depth), 0, 1, -power, power)
		let ynvel= map(noise(this.pos.y/100, frameCount/100, this.depth), 0, 1, -power, power)
		this.wave= createVector(xnvel, ynvel)
			}
	}	
	this.pos.add(this.wave)
		if(!mouseMoving && this.wave.mag()>0){	
			this.wave.mult(0.99)
			if(this.wave.mag()<0.01){
				this.wave.setMag(0)
			}
		}	
	}

show(){
	push()
	let size= map(this.depth, -20, 20, minSize, maxSize)
	let alpha=map(this.depth, 0, 20, 0, 150)
	blur= map(abs(this.depth), 0, 20, 0, maxSize)
	drawingContext.shadowOffsetX = -size/4;
  drawingContext.shadowOffsetY = size/4;
  drawingContext.shadowBlur = blur;

	noStroke()
let g= bg.get(this.pos.x, this.pos.y)
let bger= (g[0]+g[1]+g[2])/3
let b= map(bger, 0, 100, 0, 255)
drawingContext.shadowColor = color(b)
fill(20+b, 255-alpha)
ellipse(this.pos.x, this.pos.y, size)
	pop()

}

}

